import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"恕","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-恕.md","filePath":"50-概念资料/dict-恕.md","lastUpdated":1778155802000}'),i={name:"50-概念资料/dict-恕.md"};function l(d,t,h,u,n,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="恕" tabindex="-1">恕 <a class="header-anchor" href="#恕" aria-label="Permalink to &quot;恕&quot;">​</a></h1><blockquote><p>传统：儒家（&quot;己所不欲，勿施于人&quot;）| 佛家对应：慈悲 | 道家对应：不争</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;恕&quot;就是<strong>推己及人</strong>——你不想被怎样对待，就不要那样对待别人。这是了空居士判断是非的<strong>底线标准</strong>。</p><p>他说：日本人侵华，他们说是在&quot;帮助落后民族&quot;，但&quot;己所不欲，勿施于人&quot;——你不想被侵略，就别侵略别人。这个底线一拉，是非立判。恕是整体观的&quot;底线版&quot;——当你无法做完整的整体分析时，先用恕来检验：你希望别人这样对你吗？</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;己所不欲，勿施于人——这是底线的整体观。你不想被侵略，就别侵略别人。&quot; — <a href="/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a></p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>恕就是原谅一切</td><td>恕首先是&quot;不做伤害别人的事&quot;，其次才是原谅</td></tr><tr><td>恕就是软弱</td><td>恕是底线的智慧——判断是非最快的检验标准</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-正">dict-正</a> — 恕是判断&quot;正&quot;的底线标准</li><li><a href="/50-概念资料/dict-处世">dict-处世</a> — 恕是处世的核心原则</li><li><a href="/50-概念资料/dict-中道">dict-中道</a> — 恕让你不偏于自利，也不偏于自损</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">model-圆融中和</a> — 恕是中道的底线操作</li><li><a href="/meta-整体观">meta-整体观</a> — 恕是最简洁的整体观检验</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>每次想批评别人之前，先问自己&quot;如果别人这样批评我，我能接受吗？&quot; 做任何决策，先用&quot;己所不欲勿施于人&quot;过滤一遍。</p>',15)])])}const b=a(i,[["render",l]]);export{s as __pageData,b as default};
